import React from 'react';
import Header from './Header.js';
import Clock from './Clock.js';
import Pomobtn from './Pomobtn.js';
import Timer from './Timer.js';
import Start from './Start.js';
import Description from './Description.js';
import TaskManager from './TaskManager.js';
import useFunctions from './hooks/useHomeFunctions.js';
import useFetch from './hooks/useFetch.js';
import Quotes from './Quotes.js';

function Home() {
  const {
    pomoInput,
    setPomoInput,
    longInput,
    setLongInput,
    shortInput,
    setShortInput,
    color,
    setColor,
    backgroundPicture,
    setBackgroundPicture,
    time,
    formatTime,
    handleStart,
    handlePause,
    handleReset,
    handleButtonClick,
  } = useFunctions();

  return (
    <div className="App">
      <div className="contentWrap">
        <Header
          pomoInput={pomoInput}
          setPomoInput={setPomoInput}
          longInput={longInput}
          setLongInput={setLongInput}
          shortInput={shortInput}
          setShortInput={setShortInput}
          color={color}
          setColor={setColor}
          backgroundPicture={backgroundPicture}
          setBackgroundPicture={setBackgroundPicture}
          isLoggedIn={false}
        />
        <div className="contentContainer">
          <Clock />
          <Pomobtn
            pomoTime={`${pomoInput}:00`}
            longTime={`${longInput}:00`}
            shortTime={`${shortInput}:00`}
            onClick={handleButtonClick}
          />
          <Timer time={formatTime(time)} />
          <Start
            onStart={handleStart}
            onPause={handlePause}
            onReset={handleReset}
          />
        </div>
      </div>

      <TaskManager />
      <Description />
    </div>
  );
}

export default Home;
